S=<SCRATCH>; cat > $S/next7/kloop.c <<'EOF'
/* The k-blocked kernel's 8x48 inner loop alone (A rows strided, B tile packed), L1-resident, against a
 * register-only loop of 24 independent FMAs: TSC cycles an iteration (24 FMAs). */
#include <immintrin.h>
#include <stdio.h>
#include <stdlib.h>
#include <x86intrin.h>
#define K 128
static float bt[K * 48] __attribute__((aligned(64)));
static float a[8 * K] __attribute__((aligned(64)));
static float out[8 * 48] __attribute__((aligned(64)));
__attribute__((noinline, target("avx512f"))) static void block(const float *ap, size_t lda, int rep) {
  for (int q = 0; q < rep; q++) {
    __m512 acc0[8], acc1[8], acc2[8];
    for (int r = 0; r < 8; r++) acc0[r] = acc1[r] = acc2[r] = _mm512_setzero_ps();
    for (size_t l = 0; l < K; l++) {
      __m512 b0 = _mm512_load_ps(bt + l * 48), b1 = _mm512_load_ps(bt + l * 48 + 16), b2 = _mm512_load_ps(bt + l * 48 + 32);
      for (int r = 0; r < 8; r++) {
        __m512 av = _mm512_set1_ps(ap[r * lda + l]);
        acc0[r] = _mm512_fmadd_ps(av, b0, acc0[r]); acc1[r] = _mm512_fmadd_ps(av, b1, acc1[r]); acc2[r] = _mm512_fmadd_ps(av, b2, acc2[r]);
      }
    }
    for (int r = 0; r < 8; r++) { _mm512_store_ps(out + r * 48, acc0[r]); _mm512_store_ps(out + r * 48 + 16, acc1[r]); _mm512_store_ps(out + r * 48 + 32, acc2[r]); }
  }
}
__attribute__((noinline, target("avx512f"))) static void regs(int rep) {
  __m512 acc[24], b = _mm512_set1_ps(1.0000001f), c = _mm512_set1_ps(0.999999f);
  for (int r = 0; r < 24; r++) acc[r] = _mm512_set1_ps((float)r);
  for (long q = 0; q < (long)rep * K; q++)
    for (int r = 0; r < 24; r++) acc[r] = _mm512_fmadd_ps(acc[r], b, c);
  for (int r = 0; r < 24; r++) _mm512_store_ps(out + (r % 8) * 48 + 16 * (r / 8), acc[r]);
}
int main(void) {
  for (int i = 0; i < K * 48; i++) bt[i] = (float)(i % 7) * 0.01f;
  for (int i = 0; i < 8 * K; i++) a[i] = (float)(i % 5) * 0.02f;
  for (int t = 0; t < 3; t++) {
    unsigned long long t0 = __rdtsc(); block(a, K, 20000); unsigned long long t1 = __rdtsc();
    regs(20000); unsigned long long t2 = __rdtsc();
    double it = 20000.0 * K;
    printf("kernel loop %.2f TSC/iter (%.1f FMA/TSC)  regs %.2f TSC/iter (%.1f FMA/TSC)  kernel/regs %.3f\n",
           (t1 - t0) / it, 24 * it / (t1 - t0), (t2 - t1) / it, 24 * it / (t2 - t1), (double)(t1 - t0) / (t2 - t1));
  }
  return out[3] == 12345.f;
}
EOF
