/* The binary32 attention's stored forward (EXP|LOWER|BANDS, the trainer's word) and backward (EXP|BANDS)
 * from LIB, one thread (no pool) or a pool of THREADS, at B x T rows, H heads, KV heads, D dims; per case
 * the median of ROUNDS calls of each after a warm one, in TSC cycles a causal probability (b*h*t(t+1)/2).
 * usage: att_scale LIB THREADS ROUNDS H KV D B:T...  */
#define _POSIX_C_SOURCE 200809L
#include <dlfcn.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <x86intrin.h>
typedef struct opaque_pool pool_t;
typedef void (*fwd_fn)(pool_t *, unsigned, size_t, size_t, size_t, size_t, size_t, const float *, const float *, const float *, float *, float *, int *);
typedef void (*bwd_fn)(pool_t *, unsigned, size_t, size_t, size_t, size_t, size_t, const float *, const float *, const float *, float *, const float *, float *, float *, float *);
typedef size_t (*psize_fn)(unsigned);
typedef pool_t *(*pinit_fn)(void *, size_t, unsigned);
static void *sym(void *h, const char *n) { void *f = dlsym(h, n); if (!f) { fprintf(stderr, "missing %s\n", n); exit(1); } return f; }
static float *fill(size_t n, float f) { float *p = aligned_alloc(64, ((n * 4 + 63) / 64) * 64); for (size_t i = 0; i < n; i++) p[i] = sinf((float)i * f) * 0.5f; return p; }
static int cmp(const void *a, const void *b) { double x = *(const double *)a, y = *(const double *)b; return x < y ? -1 : x > y; }
int main(int argc, char **argv) {
  void *h = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL); unsigned threads = (unsigned)atoi(argv[2]); int rounds = atoi(argv[3]);
  size_t H = atoi(argv[4]), KV = atoi(argv[5]), D = atoi(argv[6]); pool_t *pool = NULL;
  fwd_fn fwd; bwd_fn bwd;
  if (!h) { fprintf(stderr, "%s\n", dlerror()); return 1; }
  *(void **)&fwd = sym(h, "bcir_tensor_attention_contract_scan_pool");
  *(void **)&bwd = sym(h, "bcir_tensor_attention_backward_contract_pool");
  if (threads > 1) {
    psize_fn ps; pinit_fn pi; *(void **)&ps = sym(h, "bcir_tensor_pool_size"); *(void **)&pi = sym(h, "bcir_tensor_pool_init");
    size_t need = ps(threads); void *mem = aligned_alloc(64, (need + 63) / 64 * 64); pool = pi(mem, need, threads);
  }
  for (int c = 7; c < argc; c++) {
    size_t B, T; if (sscanf(argv[c], "%zu:%zu", &B, &T) != 2) return 2;
    float *q = fill(B * T * H * D, 0.37f), *k = fill(B * T * KV * D, 0.53f), *v = fill(B * T * KV * D, 0.71f);
    float *p = fill(B * H * T * T, 0.0f), *y = fill(B * T * H * D, 0.1f), *dy = fill(B * T * H * D, 0.29f);
    float *dq = fill(B * T * H * D, 0.f), *dk = fill(B * T * KV * D, 0.f), *dv = fill(B * T * KV * D, 0.f);
    double tf[200], tb[200], probs = (double)B * H * T * (T + 1) / 2; int bad = 0;
    for (int r = -1; r < rounds; r++) {
      unsigned long long t0 = __rdtsc();
      fwd(pool, 1u | 16u | 32u, B, T, H, KV, D, q, k, v, p, y, &bad);
      unsigned long long t1 = __rdtsc();
      bwd(pool, 1u | 32u, B, T, H, KV, D, q, k, v, p, dy, dq, dk, dv);
      unsigned long long t2 = __rdtsc();
      if (r >= 0) { tf[r] = (double)(t1 - t0); tb[r] = (double)(t2 - t1); }
    }
    qsort(tf, rounds, sizeof(double), cmp); qsort(tb, rounds, sizeof(double), cmp);
    printf("threads %u B%zu T%zu H%zu KV%zu D%zu: fwd %8.1f us %5.2f TSC/prob/thread   bwd %8.1f us %5.2f TSC/prob/thread  (bad %d)\n",
           threads, B, T, H, KV, D, tf[rounds / 2] / 2300.0, tf[rounds / 2] * (threads > 1 ? threads : 1) / probs,
           tb[rounds / 2] / 2300.0, tb[rounds / 2] * (threads > 1 ? threads : 1) / probs, bad);
    free(q); free(k); free(v); free(p); free(y); free(dy); free(dq); free(dk); free(dv);
  }
  return 0;
}
EOF
