S=<SCRATCH>; cat > $S/next7/loss_parts.c <<'EOF'
/* loss_task's loops a pass at a time over N rows of V logits (one thread, the trainer's flags):
 * the max, the exponentials and their sum, the adjoints (two divisions), the adjoints with the
 * division by n as a product by 1/n (n a power of two), and the whole task as the trainer runs it. */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <x86intrin.h>
#define N 2048
#define V 1024
static float logits[N * V], dl[N * V], dl2[N * V];
static double terms[N], ebuf[N][V];
static uint32_t tg[N];
static float maxs[N]; static double sums[N];
int main(void) {
  for (size_t i = 0; i < (size_t)N * V; i++) logits[i] = sinf((float)i * 0.37f) * 3.0f;
  for (int i = 0; i < N; i++) tg[i] = (uint32_t)((5 * i + 1) % V);
  for (int rep = 0; rep < 4; rep++) {
    unsigned long long t0 = __rdtsc();
    for (int i = 0; i < N; i++) { const float *row = logits + (size_t)i * V; float m = row[0]; for (int j = 1; j < V; j++) if (row[j] > m) m = row[j]; maxs[i] = m; }
    unsigned long long t1 = __rdtsc();
    for (int i = 0; i < N; i++) { const float *row = logits + (size_t)i * V; double s = 0.0; float m = maxs[i]; for (int j = 0; j < V; j++) { ebuf[i][j] = exp((double)row[j] - m); s += ebuf[i][j]; } sums[i] = s; terms[i] = log(s) + (double)m - row[tg[i]]; }
    unsigned long long t2 = __rdtsc();
    for (int i = 0; i < N; i++) { float *d = dl + (size_t)i * V; double s = sums[i]; size_t t = tg[i]; for (size_t j = 0; j < V; j++) d[j] = (float)((ebuf[i][j] / s - (j == t ? 1.0 : 0.0)) / (double)N); }
    unsigned long long t3 = __rdtsc();
    for (int i = 0; i < N; i++) { float *d = dl2 + (size_t)i * V; double s = sums[i], inv = 1.0 / (double)N; size_t t = tg[i]; for (size_t j = 0; j < V; j++) d[j] = (float)((ebuf[i][j] / s - (j == t ? 1.0 : 0.0)) * inv); }
    unsigned long long t4 = __rdtsc();
    double per = (double)N * V;
    printf("TSC a logit: max %.2f  exp+sum %.2f  adjoint(2 div) %.2f  adjoint(div, *1/n) %.2f  same bytes %d\n",
           (t1 - t0) / per, (t2 - t1) / per, (t3 - t2) / per, (t4 - t3) / per, !memcmp(dl, dl2, sizeof dl));
  }
  return 0;
}
EOF
