#include <math.h>
#include <stdio.h>
#include <x86intrin.h>
#define N 2048
#define V 1024
static float logits[N * V]; static double e[V]; static float maxs[N];
int main(void) {
  for (size_t i = 0; i < (size_t)N * V; i++) logits[i] = sinf((float)i * 0.37f) * 3.0f;
  for (int i = 0; i < N; i++) maxs[i] = 3.0f;
  volatile double sink = 0;
  for (int rep = 0; rep < 4; rep++) {
    unsigned long long t0 = __rdtsc(); double tot = 0;
    for (int i = 0; i < N; i++) { const float *row = logits + (size_t)i * V; float m = maxs[i]; for (int j = 0; j < V; j++) e[j] = exp((double)row[j] - m); tot += e[5]; }
    unsigned long long t1 = __rdtsc();
    for (int i = 0; i < N; i++) { const float *row = logits + (size_t)i * V; float m = maxs[i]; double s = 0; for (int j = 0; j < V; j++) { e[j] = exp((double)row[j] - m); s += e[j]; } tot += s; }
    unsigned long long t2 = __rdtsc();
    for (int i = 0; i < N; i++) { const float *row = logits + (size_t)i * V; float m = maxs[i]; double s = 0; for (int j = 0; j < V; j++) e[j] = exp((double)row[j] - m); for (int j = 0; j < V; j++) s += e[j]; tot += s; }
    unsigned long long t3 = __rdtsc();
    sink = tot; double per = (double)N * V;
    printf("TSC a logit: exp only %.2f  exp+sum fused %.2f  exp then sum %.2f\n", (t1 - t0) / per, (t2 - t1) / per, (t3 - t2) / per);
  }
  (void)sink; return 0;
}
